import{_ as e,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）","description":"太棒了，我们继续进入： 🌐 ✅ 本章目标： 基于我们前面构建的模块依赖关系 生成一个 交互式 HTML 页面 支持：点击模块节点 → 展示模块代码内容 无需 Graphviz，浏览器直接查看 🧱 项目结构（新增） htmlvizbundler/├── src/│ ├── main。","frontmatter":{"title":"第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"太棒了，我们继续进入： 🌐 ✅ 本章目标： 基于我们前面构建的模块依赖关系 生成一个 交互式 HTML 页面 支持：点击模块节点 → 展示模块代码内容 无需 Graphviz，浏览器直接查看 🧱 项目结构（新增） htmlvizbundler/├── src/│ ├── main。","sidebarWeight":48,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）.md"}'),l={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）.md"};function d(a,t,n,i,g,p){return o(),r("div",null,[...t[0]||(t[0]=[s('<div><h1 id="第十三章-生成-html-可视化模块依赖图-可点击查看内容" tabindex="-1">第十三章：生成 HTML 可视化模块依赖图（可点击查看内容） <a class="header-anchor" href="#第十三章-生成-html-可视化模块依赖图-可点击查看内容" aria-label="Permalink to &quot;第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）&quot;">​</a></h1><blockquote><p>本节目标：理解“第十三章：生成 HTML 可视化模块依赖图（可点击查看内容）”的核心思路，并能把它用于实际开发或面试表达。 太棒了，我们继续进入：</p></blockquote><p><strong>🌐</strong> ✅ 本章目标：</p><ul><li>基于我们前面构建的模块依赖关系</li><li>生成一个<strong>交互式 HTML 页面</strong></li><li>支持：点击模块节点 → 展示模块代码内容</li><li>无需 Graphviz，浏览器直接查看</li></ul><p><strong>🧱</strong> <strong>项目结构（新增）</strong> htmlvizbundler/├── src/│ ├── main.mjs│ ├── a.mjs│ └── b.mjs├── bundler.js└── dist/ ├── bundle.js └── graph.html # ✅ HTML 可视化输出</p><p><strong>✨</strong> <strong>可视化效果：</strong></p><ul><li>模块名以节点图显示（box）</li><li>连线表示依赖关系</li><li>点击模块名 → 展示其代码内容（右侧预览）</li><li>全部基于 HTML + JS + SVG 渲染</li></ul><p><strong>✅</strong> <strong>bundler.js：添加 HTML 依赖图导出功能</strong> 在打包后添加如下方法：</p><p><strong>✍️</strong> <strong>添加 generateHtmlGraph(modules) 函数</strong> function escapeHTML(str) { return str.replace(/[&lt;&gt;&amp;&quot;]/g, (ch) =&gt; ({ &#39;&lt;&#39;: &#39;&lt;&#39;, &#39;&gt;&#39;: &#39;&gt;&#39;, &#39;&amp;&#39;: &#39;&amp;&#39;, &#39;&quot;&#39;: &#39;&quot;&#39; }[ch]));} function generateHtmlGraph(modules) { const nodes = modules.map(m =&gt; { return <code>\\&lt;div class=&quot;node&quot; data-id=&quot;${m.id}&quot; onclick=&quot;showCode(${m.id})&quot;\\&gt;${m.name}\\&lt;/div\\&gt;</code>; }).join(&#39;&#39;); const edges = modules.flatMap(m =&gt; { return m.deps.map(dep =&gt; { const targetAbs = path.resolve(path.dirname(m.absPath), dep.endsWith(&#39;.json&#39;) || dep.endsWith(&#39;.mjs&#39;) ? dep : dep + &#39;.js&#39;); const target = modules.find(t =&gt; t.absPath === targetAbs); return target ? <code>\\&lt;line x1=&quot;${m.id * 150 + 80}&quot; y1=&quot;40&quot; x2=&quot;${target.id * 150 + 80}&quot; y2=&quot;40&quot; stroke=&quot;gray&quot; /\\&gt;</code> : &#39;&#39;; }); }).join(&#39;&#39;); const scripts = <code>\\&lt;script\\&gt;const codes = $\\{JSON.stringify(modules.reduce((acc, m) =\\&gt; \\{ acc[m.id] = escapeHTML(m.rawCode); return acc;\\}, \\{\\}))\\}; function showCode(id) \\{ document.getElementById(&#39;code&#39;).innerHTML = &#39;\\&lt;pre\\&gt;&#39; + codes[id] + &#39;\\&lt;/pre\\&gt;&#39;;\\}\\&lt;/script\\&gt;</code>; return <code>\\&lt;!DOCTYPE html\\&gt;\\&lt;html\\&gt;\\&lt;head\\&gt; \\&lt;meta charset=&quot;utf-8&quot; /\\&gt; \\&lt;style\\&gt; body { font-family: sans-serif; display: flex; } .graph { padding: 20px; min-width: 400px; } .node { padding: 5px 10px; margin: 8px; border: 1px solid #aaa; border-radius: 6px; display: inline-block; background: #eef; cursor: pointer; } #code { padding: 20px; background: #f7f7f7; border-left: 1px solid #ccc; white-space: pre-wrap; flex: 1; } \\&lt;/style\\&gt;\\&lt;/head\\&gt;\\&lt;body\\&gt; \\&lt;div class=&quot;graph&quot;\\&gt; \\&lt;h3\\&gt;模块依赖图\\&lt;/h3\\&gt; ${nodes} \\&lt;svg width=&quot;100%&quot; height=&quot;80&quot;\\&gt;${edges}\\&lt;/svg\\&gt; \\&lt;/div\\&gt; \\&lt;div id=&quot;code&quot;\\&gt;\\&lt;em\\&gt;点击模块查看源码\\&lt;/em\\&gt;\\&lt;/div\\&gt; ${scripts}\\&lt;/body\\&gt;\\&lt;/html\\&gt;</code>;}</p><p><strong>✍️</strong> <strong>在打包流程末尾加上：</strong> const html = generateHtmlGraph(modules);fs.writeFileSync(&#39;dist/graph.html&#39;, html, &#39;utf-8&#39;);console.log(&#39;✅ 可视化 HTML 依赖图生成完成：dist/graph.html&#39;);</p><p><strong>✅</strong> <strong>运行打包</strong> node bundler.js src/main.mjs --out dist/bundle.js 然后打开 dist/graph.html，就能：</p><ul><li>浏览依赖结构图</li><li>点击每个模块查看代码内容</li></ul><p><strong>🧾</strong> <strong>效果截图（示意）：</strong> +-------------------------+| src/main.mjs | ◀── 点击 → 展示源码+-------------------------+ ↓ ↓+----------------+ +----------------+| src/a.mjs | | src/b.mjs |+----------------+ +----------------+</p><p><strong>✅</strong> <strong>本章成果</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>能力</strong></td><td><strong>实现</strong></td></tr><tr><td>输出模块关系可视化 HTML</td><td>✔</td></tr><tr><td>点击节点查看模块源码</td><td>✔</td></tr><tr><td>无需 Graphviz，纯浏览器实现</td><td>✔</td></tr><tr><td>支持所有类型模块（json/cjs/esm）</td><td>✔</td></tr></tbody></table><p><strong>🔮</strong> <strong>下一章预告（第十四章）</strong> 你已经实现了一个包含：</p><ul><li>模块分析器</li><li>模拟打包器</li><li>Tree Shaking</li><li>top-level await</li><li>动态导入</li><li>CommonJS 和 JSON 混合模块</li><li>可视化工具</li></ul><p>下一章可以挑战： <strong>支持多入口打包（MPA 或微前端）+ 自动共享模块（缓存）分析</strong> 是否继续？我带你完成真正可应用的微型打包器构建体系 ✅ &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const m=e(l,[["render",d]]);export{u as __pageData,m as default};
